// About/Education background: the X of École polytechnique drawn by one chain
// of Fourier epicycles, then sharpened by adding terms, then filled.
//
// GENERATED by animation/build-fourier-x.mjs from fourier-x.template.js.
//
// Markup: an empty layer inside a positioned container,
//   <div class="aboutme-fourier" data-fourier-x
//        data-mobile="education" data-desktop="summary education"></div>
// The layer is sized to cover the elements whose ids are listed for the
// current breakpoint. Colours come from --color-accent / --color-text-subtle.
(() => {
  const layer = document.querySelector("[data-fourier-x]");
  if (!layer || !window.requestAnimationFrame) {
    return;
  }

  // Fourier coefficients of the X outline (traced from assets/logo-l-x.jpg by
  // the build): flat [freq, re, im, ...] with re/im scaled by COEF_SCALE, DC
  // term first, then by decreasing amplitude. Units: source image pixels.
  const SHAPE_W = 132.4;
  const SHAPE_H = 160.2;
  const COEF_SCALE = 1000;
  const TERMS = [
    [0,-3189,854,1,-36182,-40031,-3,-20453,-16417,5,-5645,-9236,-1,3381,-4863,3,1450,-1508,-11,-1736,-833,13,-256,-1451,-5,827,-1013,-2,602,-1044,4,-327,864,7,-592,396,9,-85,-677,-4,645,-124,2,-493,-385,-7,-240,-576,-19,-595,-98,6,-522,-139,21,83,-509,-8,343,193,-6,-346,-153,-10,-122,-304,12,-216,224,15,-287,85,-12,282,-96,-27,-268,31,8,53,254,11,-248,-9,29,109,-209,-13,133,-191,-16,185,34,23,-172,-14,17,42,-158,-20,125,-104,-15,-25,-159,-14,-153,-16,14,-147,-46,20,-142,54,19,-140,-55,-18,-75,-129,-35,-136,58,10,-17,-143,37,96,-85,-21,27,-111,-24,109,-25,31,-102,-39,28,-103,5,-28,53,-82,27,-81,-50,-9,-15,-88,39,-73,-51,-23,-20,-84,-26,-59,-64,-32,74,-40,22,-80,-23,-22,-69,45,-43,-64,46,-36,14,-76,16,-16,76,45,67,-28,-29,5,-72,35,-47,-54,36,-63,-20,-37,-13,-63,-34,-54,-34,-40,42,-48,25,32,-54,47,-37,-50,-17,-26,-53,-44,-4,-52,-31,-17,-48,43,-19,-46,55,-16,-46,44,-40,-24,-51,-27,38,-48,16,-44,38,-42,-17,24,-11,43,30,-42,-13,-52,-15,-40,-42,-39,-18,-30,-21,37,-45,-17,-37,53,40,-2,-56,4,-39,-38,13,36,51,-9,-35,63,-3,-36,33,25,-22,52,-20,-27,-53,-24,-21,-60,-17,-27,-46,22,23,-54,30,8,-39,-9,-29,-50,-30,-2,54,-23,-19,40,-17,25,32,-20,22,-62,28,-8,-25,-18,-22,46,-25,-14,-64,-4,-27,-78,15,-22,-59,-12,24,71,9,-25,42,-20,16,-70,22,-13,58,-25,0,48,-15,20,50,-24,4,64,-22,11,34,-13,20,-86,8,-22,-33,-20,-11,62,-16,-17,60,-12,-20,-94,2,-23,-68,-16,-16,56,-18,14,61,21,7,-72,-10,-20,-61,-19,-10,80,-21,0,59,4,-20,72,-20,3,-58,-20,3,-47,-13,-14,67,6,-18,79,11,-15,66,-18,-5,-76,-17,-7,68,-6,-17,88,-17,-4,96,-15,-9,70,-9,-15,-84,-17,-4,-102,-5,-16,-69,-17,1,-80,-12,-12,-55,-7,-15,112,-9,-13,-41,-15,-5,-66,-14,7,78,-4,-15,74,-12,-10,-67,-3,15,104,-10,-11,82,-8,-12,-118,-11,-9,-92,-14,1,-110,-8,-12,41,14,0,-88,-11,-8,69,6,12,87,12,-6,120,-4,-12,75,8,-10,-77,-13,2,128,-1,-12,26,3,12,-100,-12,3,73,-8,9,-75,1,12,76,-2,-12,81,-9,7,-74,-6,10,-134,-11,-4,86,-1,-11,-126,-10,-4,95,10,3,94,1,-10,90,-5,-9,49,9,6,-96,-10,0,18,10,-2,100,-7,-6,57,0,9,-63,-7,-6,136,1,-9,77,2,9,-108,-8,4,-142,-9,2,65,-3,8,91,6,-5,108,-3,-8,83,8,-3,124,-3,-8,102,1,-8,84,-2,-8,-83,3,7,-91,3,7,144,6,-5,-160,-4,-7,93,-7,0,-49,-6,-4,103,6,4,105,-6,-4,113,-6,-4,98,1,-7,-81,1,-7,116,-1,-7,89,-6,2,92,0,-7,-297,3,6,106,0,-7,118,6,-1,143,-6,0,140,3,-6,152,5,-4,-150,-6,1,97,-6,-2,-104,-6,2,-85,-4,5,160,6,1,121,-6,-1,148,5,-4,129,-5,-3,-71,-4,-4,-158,-6,-1,-99,2,6,-112,-5,2,-105,-3,-5,-240,-3,-5,151,-5,-3,-166,-5,3,246,-4,-4,-163,1,-5,225,0,-5,-89,-1,-5,-133,-3,-4,114,-2,-5,111,3,4,85,-4,4,-176,-5,-1,-97,-1,-5,-147,5,-2,256,1,-5,-116,-4,3,-231,-3,4,-239,-2,5,205,4,-2,117,-4,-2,-184,-5,0,-82,0,5,135,-5,1,-127,-3,-4,167,-4,-3,-139,5,-1,-98,4,3,510,4,-3,154,-3,-4,-481,-3,-4,-244,4,2,-508,4,-3,-496,-2,-4,-119,-2,-4],
  ];

  const DESKTOP = window.matchMedia("(min-width: 769px)"); // matches styles.css breakpoints
  const FIT = 0.82; // fraction of the layer the X may fill

  const SAMPLES = 1024; // points per contour when drawing
  const N_TRACE = 16; // terms used by the epicycles
  const N_MAX = 256; // terms at the end of the convergence phase
  const MAX_DPR = 1.5; // faint background: full retina resolution is wasted memory

  // Timeline (seconds)
  const T_TRACE = 5;
  const T_HOLD = 0.6;
  const T_CONVERGE = 3.2;

  // How the animation ends — data-end on the element, or ?fx-end=… in the URL
  // to compare without editing the HTML:
  //   "outline"   the converged curve stays a line; the stroke pulses once
  //   "fill"      the shape fills in and stays filled
  //   "fill-fade" fills in, holds, then fades back to the outline
  const END_DURATIONS = { outline: 0.9, fill: 1.2, "fill-fade": 2.4 };
  const END = (() => {
    let v = null;
    try {
      v = new URLSearchParams(window.location.search).get("fx-end");
    } catch (error) {
      // Ignore malformed URLs.
    }
    v = v || layer.dataset.end;
    return Object.hasOwn(END_DURATIONS, v) ? v : "outline";
  })();
  layer.dataset.end = END; // CSS tunes the layer's opacity per style
  const T_END = END_DURATIONS[END];
  const T_TOTAL = T_TRACE + T_HOLD + T_CONVERGE + T_END;

  // ---------- layout: cover the target sections ----------

  const targets = () =>
    (layer.dataset[DESKTOP.matches ? "desktop" : "mobile"] || "")
      .split(/\s+/)
      .map((id) => id && document.getElementById(id))
      .filter(Boolean);

  const place = () => {
    const els = targets();
    const parent = layer.offsetParent;
    if (!els.length || !parent) {
      layer.style.display = "none";
      return;
    }
    const base = parent.getBoundingClientRect();
    let top = Infinity, bottom = -Infinity;
    for (const el of els) {
      const r = el.getBoundingClientRect();
      top = Math.min(top, r.top);
      bottom = Math.max(bottom, r.bottom);
    }
    layer.style.display = "";
    layer.style.top = `${top - base.top}px`;
    layer.style.height = `${bottom - top}px`;
  };

  // ---------- Fourier series ----------

  const COS = new Float64Array(SAMPLES);
  const SIN = new Float64Array(SAMPLES);
  for (let m = 0; m < SAMPLES; m++) {
    COS[m] = Math.cos((2 * Math.PI * m) / SAMPLES);
    SIN[m] = Math.sin((2 * Math.PI * m) / SAMPLES);
  }

  // z(t) = Σ c_f e^{2πi f t}, terms in chaining / detail order.
  const unpack = (flat) => {
    const terms = [];
    for (let i = 0; i < flat.length; i += 3) {
      const freq = flat[i];
      const re = flat[i + 1] / COEF_SCALE;
      const im = flat[i + 2] / COEF_SCALE;
      terms.push({ freq, step: ((freq % SAMPLES) + SAMPLES) % SAMPLES, re, im, amp: Math.hypot(re, im) });
    }
    return terms;
  };

  // Partial sum with a fractional number of terms n (the last term is
  // weighted by n - floor(n) so the curve sharpens continuously).
  const partialSum = (terms, n, out) => {
    const M = SAMPLES;
    const whole = Math.floor(n);
    const frac = n - whole;
    out.fill(0);
    const count = Math.min(terms.length, whole + 1);
    for (let i = 0; i < count; i++) {
      const t = terms[i];
      const w = i < whole ? 1 : frac;
      if (w === 0) continue;
      const re = t.re * w, im = t.im * w;
      let m = 0;
      for (let j = 0; j < M; j++) {
        out[2 * j] += re * COS[m] - im * SIN[m];
        out[2 * j + 1] += re * SIN[m] + im * COS[m];
        m += t.step;
        if (m >= M) m -= M;
      }
    }
    return out;
  };

  let shapes = null; // computed lazily on first play

  const buildShapes = () =>
    TERMS.map((flat) => {
      const terms = unpack(flat);
      return { terms, rough: partialSum(terms, N_TRACE, new Float64Array(2 * SAMPLES)) };
    });

  // ---------- rendering ----------

  const canvas = document.createElement("canvas");
  canvas.style.cssText = "display:block;width:100%;height:100%;";
  layer.appendChild(canvas);
  const ctx = canvas.getContext("2d");
  const scratch = new Float64Array(2 * SAMPLES);

  const clamp01 = (x) => Math.max(0, Math.min(1, x));
  const smooth = (x) => x * x * (3 - 2 * x);

  // Fill opacity and stroke-width multiplier during the ending.
  const endState = (time) => {
    const e = clamp01((time - T_TRACE - T_HOLD - T_CONVERGE) / T_END);
    if (END === "fill") return { fill: smooth(e), pulse: 1 };
    if (END === "fill-fade") {
      return { fill: smooth(clamp01(e / 0.35)) * (1 - smooth(clamp01((e - 0.6) / 0.4))), pulse: 1 };
    }
    return { fill: 0, pulse: 1 + 0.9 * Math.sin(Math.PI * e) };
  };

  const readColors = () => {
    const s = getComputedStyle(document.documentElement);
    const v = (name, fallback) => s.getPropertyValue(name).trim() || fallback;
    return {
      ink: v("--color-accent", "#2a5d8f"),
      subtle: v("--color-text-subtle", "#5f6f80"),
    };
  };

  let colors = readColors();
  let view = { scale: 1, ox: 0, oy: 0, dpr: 1 };
  let startTime = null;
  let rafId = 0;

  const px = (n) => n / view.scale; // CSS px -> shape units

  const resize = () => {
    const rect = layer.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    canvas.width = Math.max(1, Math.round(rect.width * dpr));
    canvas.height = Math.max(1, Math.round(rect.height * dpr));
    view = {
      scale: Math.min((rect.width * FIT) / SHAPE_W, (rect.height * FIT) / SHAPE_H),
      ox: rect.width / 2,
      oy: rect.height / 2,
      dpr,
    };
  };

  const tracePath = (pts, upto = SAMPLES, close = true) => {
    ctx.moveTo(pts[0], pts[1]);
    for (let j = 1; j < upto; j++) ctx.lineTo(pts[2 * j], pts[2 * j + 1]);
    if (close) ctx.closePath();
  };

  const drawEpicycles = (shape, t, alpha) => {
    const { terms } = shape;
    let x = terms[0].re, y = terms[0].im;
    ctx.lineWidth = px(0.9);
    for (let i = 1; i <= N_TRACE; i++) {
      const c = terms[i];
      const a = 2 * Math.PI * c.freq * t;
      const nx = x + c.re * Math.cos(a) - c.im * Math.sin(a);
      const ny = y + c.re * Math.sin(a) + c.im * Math.cos(a);
      ctx.globalAlpha = 0.45 * alpha;
      ctx.strokeStyle = colors.subtle;
      ctx.beginPath();
      ctx.arc(x, y, c.amp, 0, 2 * Math.PI);
      ctx.stroke();
      ctx.globalAlpha = 0.7 * alpha;
      ctx.strokeStyle = colors.ink;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(nx, ny);
      ctx.stroke();
      x = nx;
      y = ny;
    }
    ctx.globalAlpha = 1;
    return [x, y];
  };

  const draw = (time) => {
    const { scale, ox, oy, dpr } = view;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (!shapes) return;
    // Shape coordinates are centred on the X's bounding box by the build.
    ctx.setTransform(scale * dpr, 0, 0, scale * dpr, ox * dpr, oy * dpr);
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    const stroke = px(1.8);

    if (time < T_TRACE + T_HOLD) {
      // Phase 1: epicycles trace the N_TRACE-term curve.
      const t = clamp01(time / T_TRACE);
      const circleAlpha =
        smooth(clamp01(time / 0.4)) * (1 - smooth(clamp01((time - T_TRACE) / T_HOLD)));
      const upto = Math.floor(t * SAMPLES);
      for (const shape of shapes) {
        const [tx, ty] = circleAlpha > 0 ? drawEpicycles(shape, t, circleAlpha) : [0, 0];
        ctx.strokeStyle = colors.ink;
        ctx.lineWidth = stroke;
        ctx.beginPath();
        tracePath(shape.rough, upto + 1, t >= 1);
        if (t < 1) ctx.lineTo(tx, ty);
        ctx.stroke();
        if (t < 1) {
          ctx.fillStyle = colors.ink;
          ctx.beginPath();
          ctx.arc(tx, ty, px(3), 0, 2 * Math.PI);
          ctx.fill();
        }
      }
      return;
    }

    // Phase 2: converge on the outline; phase 3: fill it.
    const u = clamp01((time - T_TRACE - T_HOLD) / T_CONVERGE);
    const n = N_TRACE * Math.pow(N_MAX / N_TRACE, smooth(u));
    const { fill: fillAlpha, pulse } = endState(time);
    ctx.beginPath();
    for (const shape of shapes) tracePath(partialSum(shape.terms, n, scratch));
    if (fillAlpha > 0) {
      ctx.globalAlpha = fillAlpha;
      ctx.fillStyle = colors.ink;
      ctx.fill("evenodd");
      ctx.globalAlpha = 1;
    }
    ctx.strokeStyle = colors.ink;
    ctx.lineWidth = stroke * pulse;
    ctx.stroke();
  };

  // Once finished, replace the canvas with an inline SVG of the final frame:
  // the canvas backing store is freed, the vector stays sharp at any size, and
  // theme/resize are handled by CSS with no script.
  let done = false;
  const finish = () => {
    const r = (v) => Math.round(v * 100) / 100;
    let d = "";
    for (const shape of shapes) {
      const p = partialSum(shape.terms, N_MAX, scratch);
      d += `M${r(p[0])} ${r(p[1])}L`;
      for (let j = 1; j < SAMPLES; j++) d += `${r(p[2 * j])} ${r(p[2 * j + 1])} `;
      d += "Z";
    }
    // Same fit rule as resize(): meet = min(width·FIT/SHAPE_W, height·FIT/SHAPE_H).
    const vw = SHAPE_W / FIT, vh = SHAPE_H / FIT;
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("viewBox", `${-vw / 2} ${-vh / 2} ${vw} ${vh}`);
    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
    svg.style.cssText = "display:block;width:100%;height:100%;overflow:visible;";
    const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
    path.setAttribute("d", d);
    path.setAttribute("fill-rule", "evenodd");
    path.setAttribute("vector-effect", "non-scaling-stroke");
    path.setAttribute("stroke-linejoin", "round");
    path.setAttribute("stroke-width", "1.8");
    path.style.cssText = `fill:${END === "fill" ? "var(--color-accent,#2a5d8f)" : "none"};stroke:var(--color-accent,#2a5d8f);`;
    svg.appendChild(path);
    layer.appendChild(svg);
    canvas.width = canvas.height = 0; // release the backing store right away
    canvas.remove();
    done = true;
  };

  const tick = (now) => {
    const time = (now - startTime) / 1000;
    draw(time);
    if (time < T_TOTAL) rafId = requestAnimationFrame(tick);
    else finish();
  };

  const play = () => {
    shapes ??= buildShapes();
    cancelAnimationFrame(rafId);
    resize();
    // Reduced motion: show the finished X without animating.
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    startTime = performance.now() - (reduce ? T_TOTAL * 1000 : 0);
    rafId = requestAnimationFrame(tick);
  };

  // Repaint once when idle (after the animation, or before it has started).
  const redrawIdle = () => {
    if (startTime === null || done) return;
    const time = (performance.now() - startTime) / 1000;
    if (time >= T_TOTAL) draw(T_TOTAL);
  };

  // Re-cover the targets whenever the page reflows or the breakpoint flips.
  const relayout = () => {
    place();
    if (done) return; // the SVG scales itself
    resize();
    redrawIdle();
  };
  const ro = new ResizeObserver(relayout);
  ro.observe(layer.offsetParent || document.body);
  for (const id of `${layer.dataset.mobile || ""} ${layer.dataset.desktop || ""}`.split(/\s+/)) {
    const el = id && document.getElementById(id);
    if (el) ro.observe(el);
  }
  DESKTOP.addEventListener("change", relayout);
  place();

  const onTheme = () => {
    colors = readColors();
    redrawIdle();
  };
  new MutationObserver(onTheme).observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["data-theme"],
  });
  window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", onTheme);

  // Start once the layer reaches the lower 70% of the viewport.
  const io = new IntersectionObserver(
    (entries) => {
      if (entries.some((e) => e.isIntersecting)) {
        io.disconnect();
        play();
      }
    },
    { rootMargin: "0px 0px -30% 0px" },
  );
  io.observe(layer);
})();
